public with sharing class ContactDomainService {

    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<String, List<Contact>>();
        }

        Map<String, List<Contact>> result = new Map<String, List<Contact>>();

        for (Contact c : [SELECT Id, Email, AccountId FROM Contact WHERE AccountId IN :accountIds AND Email != null AND Email != '']) {
            String domain = getEmailDomain(c.Email);
            if (domain != null && domain.length() > 0) {
                if (!result.containsKey(domain)) {
                    result.put(domain, new List<Contact>());
                }
                result.get(domain).add(c);
            }
        }

        return result;
    }

    private static String getEmailDomain(String email) {
        if (email == null || email.length() == 0) {
            return null;
        }
        Integer atIndex = email.indexOf('@');
        if (atIndex >= 0 && atIndex < email.length() - 1) {
            return email.substring(atIndex + 1).toLowerCase().trim();
        }
        return null;
    }
}
