public class ErpSyncFinalizer implements Finalizer {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(FinalizerContext context) {
        FB_Job_Log__c jobLog = new FB_Job_Log__c();
        jobLog.Job_Name__c = 'ErpAccountSyncJob';
        jobLog.Attempt__c = attempt;

        Exception error = context.getException();
        if (error == null) {
            jobLog.Status__c = 'Success';
        } else {
            jobLog.Status__c = 'Failed';
            String errorMsg = error.getMessage();
            jobLog.Error__c = (errorMsg != null && errorMsg.length() > 255) 
                ? errorMsg.substring(0, 255) 
                : errorMsg;

            if (attempt < 3) {
                System.enqueueId(new ErpAccountSyncJob(accountIds, attempt + 1));
            }
        }

        insert jobLog;
    }
}
