public class Opportunities extends fflib_SObjectDomain {
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public SObject construct(List<SObject> sObjects) {
            return new Opportunities(sObjects);
        }
    }

    public Opportunities(List<SObject> sObjects) {
        super(sObjects);
    }

    private Set<Id> opportunitiesToProcess = new Set<Id>();
    private Boolean hasExecuted = false;

    public override void onAfterInsert() {
        for (Opportunity opp : (List<Opportunity>) getRecords()) {
            if (opp.StageName == 'Closed Won') {
                opportunitiesToProcess.add(opp.Id);
            }
        }
        executeFulfilment();
    }

    public override void onAfterUpdate() {
        for (Opportunity opp : (List<Opportunity>) getRecords()) {
            Opportunity oldOpp = (Opportunity) getOldMap().get(opp.Id);
            if (opp.StageName == 'Closed Won' && oldOpp != null && oldOpp.StageName != 'Closed Won') {
                opportunitiesToProcess.add(opp.Id);
            }
        }
        executeFulfilment();
    }

    private void executeFulfilment() {
        if (!hasExecuted && !opportunitiesToProcess.isEmpty()) {
            hasExecuted = true;
            IOpportunityFulfilmentService service = (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(opportunitiesToProcess);
        }
    }
}
