        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField field : contactSelector.getSObjectFieldList()) {
            contactFieldNames.add(field.getDescribe().getName());
        }
        String contactSubquery = 'SELECT ' + String.join(contactFieldNames, ', ') + ' FROM Contacts';

        List<String> accountFieldNames = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            accountFieldNames.add(field.getDescribe().getName());
        }
        String accountFieldsStr = String.join(accountFieldNames, ', ');

        String queryStr = 'SELECT ' + accountFieldsStr + ', (' + contactSubquery + ') FROM Account WHERE Id IN :accountIds';
        return (List<Account>) Database.query(queryStr);
    }
