        List<Map<String, Object>> payload = new List<Map<String, Object>>();
        Map<String, Object> record = new Map<String, Object>();
        record.put('salesforceId', acc.Id);
        record.put('name', acc.Name);
        record.put('country', acc.BillingCountry);
        payload.add(record);
        return payload;
    }
