```apex
public class FollowUpTaskService {
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Bulk query to fetch opportunity details for all IDs
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Name, OwnerId FROM Opportunity WHERE Id IN :opportunityIds]
        );

        List<Task> tasksToCreate = new List<Task>();

        for (Id oppId : opportunityIds) {
            Opportunity opp = oppMap.get(oppId);

            if (opp == null) {
                // If the opportunity is not found, we cannot create a task for it
                failedOpportunityIds.add(oppId);
                continue;
            }

            // Build the task record
            tasksToCreate.add(new Task(
                WhatId = opp.Id,
                OwnerId = opp.OwnerId,
                Subject = 'Follow up: ' + opp.Name,
                ActivityDate = Date.today().addDays(7),
                Status = 'Not Started',
                Priority = 'Normal'
            ));
        }

        // Perform a bulk insert with partial success enabled.
        // This avoids the "Too many DML statements" error and allows validation rule 
        // failures to fail individually without rolling back successful tasks.
        if (!tasksToCreate.isEmpty()) {
            List<Database.SaveResult> results = Database.insert(tasksToCreate, false);

            for (Integer i = 0; i < tasksToCreate.size(); i++) {
                if (!results[i].isSuccess()) {
                    // Add the Opportunity ID associated with the failed task to the result set
                    failedOpportunityIds.add(tasksToCreate[i].WhatId);
                }
            }
        }

        return failedOpportunityIds;
    }
}
```

