public with sharing class RenewalReminderService {
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Query Opportunities in bulk to avoid SOQL limits
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>();
        for (Opportunity opp : [SELECT Id, Name, OwnerId, CloseDate FROM Opportunity WHERE Id IN :opportunityIds]) {
            oppMap.put(opp.Id, opp);
        }

        List<Messaging.SingleEmailMessage> emails = new List<Messaging.SingleEmailMessage>();

        // Iterate over valid opportunities to build emails.
        // Iterating over oppMap.keySet() ensures we only process existing records
        // and handles duplicates in the input list safely.
        for (Id oppId : oppMap.keySet()) {
            Opportunity opp = oppMap.get(oppId);

            Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
            mail.setTargetObjectId(opp.OwnerId);
            mail.setSaveAsActivity(false);
            mail.setSubject('Renewal due: ' + opp.Name);
            mail.setPlainTextBody('The renewal for ' + opp.Name + ' is closing on ' + opp.CloseDate);

            emails.add(mail);
        }

        if (emails.isEmpty()) {
            return 0;
        }

        // Send emails in a single batch callout to avoid governor limits (10 callouts/transaction).
        // Calling sendEmail inside a loop for 200 records causes a System.LimitException.
        // Batching respects the limit and the default allOrNothing=false ensures
        // individual email failures do not roll back the rest.
        List<Messaging.SendEmailResult> results = Messaging.sendEmail(emails);

        Integer successCount = 0;
        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                successCount++;
            }
        }

        return successCount;
    }
}
