import { LightningElement, wire } from 'lwc';
import { subscribe, unsubscribe, publish, MessageContext, APPLICATION_SCOPE } from 'lightning/messageService';
import ACCOUNT_SELECTED from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    @wire(MessageContext) messageContext;

    selectedAccountId = null;
    subscription = null;

    connectedCallback() {
        this.subscribeToMessage();
    }

    disconnectedCallback() {
        this.unsubscribeToMessage();
    }

    subscribeToMessage() {
        if (this.subscription || !this.messageContext) return;
        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED,
            (message) => this.handleMessage(message),
            undefined,
            APPLICATION_SCOPE
        );
    }

    unsubscribeToMessage() {
        if (this.subscription) {
            unsubscribe(this.messageContext, this.subscription);
            this.subscription = null;
        }
    }

    handleMessage(message) {
        this.selectedAccountId = message && message.recordId ? message.recordId : null;
    }

    handleClear() {
        publish(this.messageContext, ACCOUNT_SELECTED, { recordId: null });
    }
}
