import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    opportunities = [];
    error = null;
    isLoading = true;

    get isEmptyState() {
        return !this.error && (!this.opportunities || this.opportunities.length === 0);
    }

    get hasData() {
        return !this.error && this.opportunities && this.opportunities.length > 0;
    }

    connectedCallback() {
        this.fetchOpportunities();
    }

    fetchOpportunities() {
        this.isLoading = true;
        this.error = null;
        this.opportunities = [];

        getOpenOpportunities({ accountId: this.recordId })
            .then(result => {
                this.opportunities = result;
                this.isLoading = false;
            })
            .catch(error => {
                this.error = error;
                this.isLoading = false;
            });
    }

    handleRetry() {
        this.fetchOpportunities();
    }
}
