import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];
    @api value;

    activeIndex = 0;

    get activeOptionId() {
        if (this.options.length === 0) return '';
        return this.options[this.activeIndex]?.value || '';
    }

    renderedCallback() {
        this.clampActiveIndex();
        if (this.options.length > 0) {
            const idx = this.options.findIndex(o => o.value === this.value);
            this.activeIndex = idx !== -1 ? idx : 0;
        }
    }

    clampActiveIndex() {
        if (this.options.length === 0) {
            this.activeIndex = 0;
        } else if (this.activeIndex >= this.options.length) {
            this.activeIndex = this.options.length - 1;
        }
    }

    handleKeyDown(event) {
        const key = event.key;
        if (!this.options.length) return;

        const selectKeys = ['Enter', ' '];
        const navKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End'];

        if (navKeys.includes(key) || selectKeys.includes(key)) {
            event.preventDefault();
        }

        if (key === 'ArrowDown') {
            this.activeIndex = Math.min(this.activeIndex + 1, this.options.length - 1);
        } else if (key === 'ArrowUp') {
            this.activeIndex = Math.max(this.activeIndex - 1, 0);
        } else if (key === 'Home') {
            this.activeIndex = 0;
        } else if (key === 'End') {
            this.activeIndex = this.options.length - 1;
        } else if (selectKeys.includes(key)) {
            this.selectOption();
        }
    }

    selectOption() {
        if (this.options.length === 0) return;
        const newValue = this.options[this.activeIndex].value;
        if (newValue === this.value) return;

        this.value = newValue;
        this.dispatchEvent(new CustomEvent('change', {
            detail: { value: newValue }
        }));
    }

    handleClick(event) {
        const optionEl = event.target.closest('li[role="option"]');
        if (optionEl) {
            const optValue = optionEl.dataset.value;
            const idx = this.options.findIndex(o => o.value === optValue);
            if (idx !== -1) {
                this.activeIndex = idx;
                this.selectOption();
            }
        }
    }
}
