public class EmployerService {
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>(employerByContactId.keySet());

        // Query existing primary affiliations for the provided contacts
        Map<Id, npe5__Affiliation__c> primaryAffMap = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
              AND npe5__Primary__c = true
        ]) {
            primaryAffMap.put(aff.npe5__Contact__c, aff);
        }

        List<npe5__Affiliation__c> toInsert = new List<npe5__Affiliation__c>();

        for (Id contactId : contactIds) {
            Id targetOrgId = employerByContactId.get(contactId);
            if (targetOrgId == null) {
                continue;
            }

            npe5__Affiliation__c currentPrimary = primaryAffMap.get(contactId);

            // Skip if the organization is already the primary affiliation
            if (currentPrimary != null && currentPrimary.npe5__Organization__c == targetOrgId) {
                continue;
            }

            // Create new primary affiliation. 
            // NPSP's standard mechanism will handle:
            // 1. Demoting the old primary to 'Former' with EndDate = TODAY
            // 2. Setting Contact.npsp__Primary_Affiliation__c to this new ID
            // 3. Marking this new affiliation as Primary
            npe5__Affiliation__c newAff = new npe5__Affiliation__c();
            newAff.npe5__Contact__c = contactId;
            newAff.npe5__Organization__c = targetOrgId;
            newAff.npe5__Status__c = 'Current';
            newAff.npe5__Primary__c = true;
            toInsert.add(newAff);
        }

        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
