public class FamilyService {
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        for (Id parentId : parentIdByChildId.values()) {
            if (parentId != null) contactIds.add(parentId);
        }
        for (Id childId : parentIdByChildId.keySet()) {
            contactIds.add(childId);
        }

        Map<String, Id> existingPairs = new Map<String, Id>();
        for (npe4__Relationship__c rel : [
            SELECT Id, npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
               OR npe4__RelatedContact__c IN :contactIds
        ]) {
            existingPairs.put(getPairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c), rel.Id);
        }

        List<npe4__Relationship__c> newRels = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (parentId == null) continue;

            if (existingPairs.containsKey(getPairKey(childId, parentId))) {
                continue;
            }

            npe4__Relationship__c rel = new npe4__Relationship__c();
            rel.npe4__Contact__c = childId;
            rel.npe4__RelatedContact__c = parentId;
            rel.npe4__Type__c = 'Parent';
            rel.npe4__Status__c = 'Current';
            newRels.add(rel);
        }

        if (!newRels.isEmpty()) {
            insert newRels;
        }
    }

    private static String getPairKey(Id id1, Id id2) {
        String s1 = String.valueOf(id1);
        String s2 = String.valueOf(id2);
        return s1.compareTo(s2) < 0 ? s1 + '-' + s2 : s2 + '-' + s1;
    }
}
