public with sharing class RecordAccessService {
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editableIds = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editableIds;
        }

        List<Id> idsToCheck = new List<Id>(recordIds);
        Integer totalSize = idsToCheck.size();

        for (Integer i = 0; i < totalSize; i += 1000) {
            Integer endIndex = Math.min(i + 1000, totalSize);
            List<Id> batch = new List<Id>();
            for (Integer j = i; j < endIndex; j++) {
                batch.add(idsToCheck.get(j));
            }

            List<UserRecordAccess> accesses = [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE RecordId IN :batch
                  AND UserId = :UserInfo.getUserId()
            ];

            for (UserRecordAccess uac : accesses) {
                if (uac.HasEditAccess) {
                    editableIds.add(uac.RecordId);
                }
            }
        }
        return editableIds;
    }
}
